import{_ as r,o,c as e,a3 as a}from"./chunks/framework.lx4Uzxpr.js";const u=JSON.parse('{"title":"减速器：力矩与转速的交换机","description":"减速器的内核是功率守恒下的力矩换转速与反射惯量平方定律；由背隙与刚度两个物理量推出谐波/RV/行星的选型规则","frontmatter":{"title":"减速器：力矩与转速的交换机","date":"2026-10-24T00:00:00.000Z","tags":["机器人","结构","传动"],"category":"notes","description":"减速器的内核是功率守恒下的力矩换转速与反射惯量平方定律；由背隙与刚度两个物理量推出谐波/RV/行星的选型规则","sidebar":false},"headers":[],"relativePath":"notes/机器人/结构与机构/reducers.md","filePath":"notes/机器人/结构与机构/reducers.md"}'),s={name:"notes/机器人/结构与机构/reducers.md"};function n(d,t,l,i,h,g){return o(),e("div",null,t[0]||(t[0]=[a('<h1 id="减速器" tabindex="-1">减速器 <a class="header-anchor" href="#减速器" aria-label="Permalink to “减速器”">​</a></h1><p><strong>一句话定义：减速器 = 用转速换力矩的功率变换器——理想下功率不变，扭矩放大 n 倍，转速降低 n 倍。</strong></p><h2 id="内核-为什么必须有它" tabindex="-1">内核：为什么必须有它 <a class="header-anchor" href="#内核-为什么必须有它" aria-label="Permalink to “内核：为什么必须有它”">​</a></h2><p>电机天然&quot;高速低扭&quot;（小型无刷的最高效率点在几千转），负载天然&quot;低速大扭&quot;（关节每秒转不过一圈却要几十牛米）。直驱方案要求电机<strong>直接输出大扭矩</strong>，意味着巨大的体积重量与惯量。减速器用一组齿轮完成交换，代价写进物理定律：</p><ol><li><strong>效率损失</strong>：$\\eta$ 典型 0.75–0.95，发热由此而来；</li><li><strong>反射惯量平方定律</strong>：折算到电机轴的负载惯量 = 负载惯量 / n²。这条定律是双刃剑——大减速比让电机&quot;感觉负载很轻&quot;，控制容易；但也让碰撞时电机难以察觉，力控的透明性变差（力控篇会回来收这个伏笔）。</li></ol><p><strong>背隙</strong>（齿与齿之间的空程）与<strong>刚度</strong>（扭转形变）是减速器仅有的两个&quot;性格参数&quot;，下面所有选型差异都从它们出发。</p><h2 id="规则与行为" tabindex="-1">规则与行为 <a class="header-anchor" href="#规则与行为" aria-label="Permalink to “规则与行为”">​</a></h2><p>三类主流方案的差异全部来自实现结构：</p><table tabindex="0"><thead><tr><th>方案</th><th>结构</th><th>背隙</th><th>刚度</th><th>适用</th></tr></thead><tbody><tr><td>行星齿轮</td><td>多个行星轮分担载荷</td><td>小（非零）</td><td>高</td><td>通用、便宜、大批量</td></tr><tr><td>RV 减速器</td><td>行星前级 + 摆线针轮后级</td><td>极小</td><td>很高</td><td>中大负载工业关节</td></tr><tr><td>谐波减速器</td><td>柔轮受控变形啮合</td><td><strong>几乎为零</strong></td><td>较低（柔轮会扭）</td><td>轻负载、高位置精度</td></tr></tbody></table><p>由此推出四条选型与使用规则：</p><ol><li><strong>减速比选择</strong>：先按负载力矩留 2 倍裕度定理论比，再用<strong>惯量匹配</strong>校验——反射后负载惯量与转子惯量之比建议 &lt; 10（比值越大，控制越&quot;软&quot;，表现为超调与振荡）。这条直接解释舵机测试里&quot;换大负载后开始抖&quot;的现象。</li><li><strong>背隙的后果</strong>：换向死区。位置环里表现为反向时的&quot;空走&quot;，闭合回路里表现为极限环振荡。需要频繁换向的关节（腕部）优先零背隙方案。</li><li><strong>刚度的后果</strong>：谐振。传动链刚度与惯量构成弹性系统，谐振频率以下的控制带宽才安全——<strong>刚度越低，可用的控制带宽越低</strong>。谐波的柔性是它换零背隙的账单。</li><li><strong>润滑与寿命</strong>：谐波柔轮疲劳是有限寿命件（按转数计），选型时查寿命曲线而不是只看额定扭矩。</li></ol><h2 id="抽象-关节模组把传动问题封装掉" tabindex="-1">抽象：关节模组把传动问题封装掉 <a class="header-anchor" href="#抽象-关节模组把传动问题封装掉" aria-label="Permalink to “抽象：关节模组把传动问题封装掉”">​</a></h2><p>&quot;电机 + 减速器 + 双编码器 + 驱动器 + 力矩传感器&quot;集成一体 = <strong>关节模组</strong>。它的意义是把&quot;选电机、选减速比、配编码器、调电流环&quot;整包封装成几个选型参数（额定扭矩/减速比/通信接口）。<a href="/notes/机器人/控制与运动生成/cascade-pid" class="term-link" title="电流环→速度环→位置环三环分层，带宽隔离原则">级联 PID</a>篇会说明：模组内部已实现三环，你拿到的只是位置指令接口——<strong>理解本文的背隙与刚度，是为了在模组行为异常时知道该怀疑哪一层</strong>。</p>',13)]))}const p=r(s,[["render",n]]);export{u as __pageData,p as default};
